"""Contact sheet for substitute teachers."""

from typing import List

from rosterkit.errors import ProjectError
from rosterkit.models import Student


def _name_of(student: Student) -> str:
    return student.display_name


def _checked(students: List[Student]) -> List[Student]:
    if not students:
        raise ProjectError("no students for contact sheet")
    for student in students:
        if not student.email:
            name = student.display_name
            raise ProjectError(f"no email for {name}")
    return sorted(students, key=_name_of)


# ---
def contact_rows(students: List[Student]) -> List[str]:
    """Text rows of name, section and email, by name."""
    ordered = _checked(students)
    wide_name = max(len(_name_of(item)) for item in ordered)
    wide_sect = max(len(item.section) for item in ordered)
    return [
        f"{_name_of(item):<{wide_name}}  "
        f"{item.section:<{wide_sect}}  {item.email}"
        for item in ordered
    ]

